                      type="text"
                      value={settings.phone || ''}
                      onChange={(e) => handleChange('phone', e.target.value)}
                      className="w-full h-11 pl-10 pr-3.5 border border-[#E8EEF9] rounded-lg bg-[#F0F7FF] text-sm text-[#0D1B3E] placeholder:text-[#6B8AFF] outline-none focus:border-[#0D1B3E] focus:bg-white focus:ring-1 focus:ring-[#0D1B3E] transition"
                      placeholder="+855 12 345 678"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-semibold text-[#0D1B3E] mb-1.5">
                    {tr('settings.email', 'Email Address', 'អ៊ីមែល')}
                  </label>
                  <div className="relative">
                    <FiMail
                      size={16}
                      className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[#6B8AFF]"
                    />
                    <input
                      type="email"
                      value={settings.email || ''}
                      onChange={(e) => handleChange('email', e.target.value)}
                      className="w-full h-11 pl-10 pr-3.5 border border-[#E8EEF9] rounded-lg bg-[#F0F7FF] text-sm text-[#0D1B3E] placeholder:text-[#6B8AFF] outline-none focus:border-[#0D1B3E] focus:bg-white focus:ring-1 focus:ring-[#0D1B3E] transition"
                      placeholder="info@scacademy.edu.kh"
                    />
                  </div>
                </div>

                <div className="md:col-span-2">
                  <label className="block text-sm font-semibold text-[#0D1B3E] mb-1.5">
                    {tr('settings.address', 'Address', 'អាសយដ្ឋាន')}
                  </label>
                  <div className="relative">
                    <FiMapPin
                      size={16}
                      className="absolute left-3.5 top-3.5 text-[#6B8AFF]"
                    />
                    <textarea
                      rows={2}
                      value={settings[addressField] || ''}
                      onChange={(e) => handleChange(addressField, e.target.value)}
                      className="w-full pl-10 pr-3.5 py-3 border border-[#E8EEF9] rounded-lg bg-[#F0F7FF] text-sm text-[#0D1B3E] placeholder:text-[#6B8AFF] outline-none focus:border-[#0D1B3E] focus:bg-white focus:ring-1 focus:ring-[#0D1B3E] transition resize-none"
                      placeholder={
                        isKhmer
                          ? 'បញ្ចូលអាសយដ្ឋានសាលា...'
                          : 'Enter school address...'
                      }
                    />
                  </div>
                </div>

                <div className="md:col-span-2">
                  <label className="block text-sm font-semibold text-[#0D1B3E] mb-1.5">
                    {tr(
                      'settings.googleMapUrl',
                      'Google Maps Link',
                      'តំណ Google Map'
                    )}
                  </label>
                  <div className="relative">
                    <FiMap
                      size={16}
                      className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[#6B8AFF]"
                    />
                    <input
                      type="url"
                      value={settings.google_map_url || ''}
                      onChange={(e) =>
                        handleChange('google_map_url', e.target.value)
                      }
                      className="w-full h-11 pl-10 pr-3.5 border border-[#E8EEF9] rounded-lg bg-[#F0F7FF] text-sm text-[#0D1B3E] placeholder:text-[#6B8AFF] outline-none focus:border-[#0D1B3E] focus:bg-white focus:ring-1 focus:ring-[#0D1B3E] transition"
                      placeholder="https://maps.google.com/..."
                    />
                  </div>
                </div>
              </div>
            </div>
          </AdminCard>

          {/* ================= SOCIAL MEDIA ================= */}
