                <FiFacebook size={19} />
              </div>
              <div>
                <h2 className="text-lg font-bold text-[#0D1B3E]">
                  {tr(
                    'settings.socialLinks',
                    'Social Media Links',
                    'បណ្តាញសង្គម'
                  )}
                </h2>
                <p className="text-xs text-[#6B8AFF] mt-0.5">
                  {tr(
                    'settings.socialLinksSubtitle',
                    'Connect your social media pages',
                    'ភ្ជាប់ទំព័របណ្តាញសង្គមរបស់សាលា'
                  )}
                </p>
              </div>
            </div>

            <div className="p-6">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
                <div>
                  <label className="block text-sm font-semibold text-[#0D1B3E] mb-1.5">
                    Facebook Page
                  </label>
                  <div className="relative">
                    <FiFacebook
                      size={16}
                      className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[#1877F2]"
                    />
                    <input
                      type="url"
                      value={settings.facebook_url || ''}
                      onChange={(e) =>
                        handleChange('facebook_url', e.target.value)
                      }
                      className="w-full h-11 pl-10 pr-3.5 border border-[#E8EEF9] rounded-lg bg-[#F0F7FF] text-sm text-[#0D1B3E] placeholder:text-[#6B8AFF] outline-none focus:border-[#0D1B3E] focus:bg-white focus:ring-1 focus:ring-[#0D1B3E] transition"
                      placeholder="https://facebook.com/..."
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-semibold text-[#0D1B3E] mb-1.5">
                    Telegram Channel
                  </label>
                  <div className="relative">
                    <FiMessageCircle
                      size={16}
                      className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[#229ED9]"
                    />
                    <input
                      type="url"
                      value={settings.telegram_url || ''}
                      onChange={(e) =>
                        handleChange('telegram_url', e.target.value)
                      }
                      className="w-full h-11 pl-10 pr-3.5 border border-[#E8EEF9] rounded-lg bg-[#F0F7FF] text-sm text-[#0D1B3E] placeholder:text-[#6B8AFF] outline-none focus:border-[#0D1B3E] focus:bg-white focus:ring-1 focus:ring-[#0D1B3E] transition"
                      placeholder="https://t.me/..."
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-semibold text-[#0D1B3E] mb-1.5">
                    YouTube Channel
                  </label>
                  <div className="relative">
                    <FiYoutube
                      size={16}
                      className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[#FF0000]"
                    />
                    <input
                      type="url"
                      value={settings.youtube_url || ''}
                      onChange={(e) =>
                        handleChange('youtube_url', e.target.value)
                      }
                      className="w-full h-11 pl-10 pr-3.5 border border-[#E8EEF9] rounded-lg bg-[#F0F7FF] text-sm text-[#0D1B3E] placeholder:text-[#6B8AFF] outline-none focus:border-[#0D1B3E] focus:bg-white focus:ring-1 focus:ring-[#0D1B3E] transition"
                      placeholder="https://youtube.com/..."
                    />
                  </div>
                </div>
              </div>
            </div>
          </AdminCard>

          {/* ================= SAVE BUTTON ================= */}
          <div className="flex items-center justify-end pt-2">
            <button
              type="submit"
              disabled={saving || uploadingLogo || uploadingFavicon}
              className="h-11 inline-flex items-center justify-center gap-2 px-8 rounded-lg bg-[#C23636] hover:bg-[#A92E2E] text-white text-sm font-semibold shadow-sm transition disabled:opacity-60 disabled:cursor-not-allowed"
            >
              {saving ? (
                <>
                  <span className="w-4 h-4 rounded-full border-2 border-white/40 border-t-white animate-spin" />
                  <span>
                    {tr('settings.saving', 'Saving...', 'កំពុងរក្សាទុក...')}
                  </span>
                </>
              ) : (
                <>
                  <FiSave size={16} />
                  <span>
                    {tr(
                      'settings.saveChanges',
                      'Save Changes',
                      'រក្សាទុកការកំណត់'
                    )}
                  </span>
                </>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AdminSettings;
